#!/usr/bin/env python3
"""Таблицы жанров для internal/domain/movies из pocketbase/hotpath/movies.py.

Запуск — через go generate (internal/domain/movies/movies.go). Вывод в stdout.
"""
import importlib.util
import pathlib
import sys

src = pathlib.Path(__file__).resolve().parents[2] / "pocketbase/hotpath/movies.py"
spec = importlib.util.spec_from_file_location("upstream_movies", src)
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

out = [
    "// Code generated by scripts/gen-movie-genres.py from pocketbase/hotpath/movies.py; DO NOT EDIT.",
    "",
    "package movies",
    "",
    "// genreOf — QID жанра Викиданных → короткий ключ. Жанры там дробные и",
    "// длинные, клиент показывает их коротко, как Кинопоиск.",
    "var genreOf = map[string]string{",
]
out += [f'\t"{q}": "{k}",' for q, k in m.GENRES.items()]
out += ["}", "", "// genreNames — ключ жанра → название на языке.", "var genreNames = map[string]map[string]string{"]
for k, names in m.GENRE_NAMES.items():
    inner = ", ".join(f'"{l}": "{n}"' for l, n in names.items())
    out.append(f'\t"{k}": {{{inner}}},')
out.append("}")
sys.stdout.write("\n".join(out) + "\n")
